  "quotes": [
    {
      "addressee": null,
      "speaker": "the Cat",
      "type": "SAYS",
      "words": "In _that_ direction,"
    },
    {
      "addressee": null,
      "speaker": "the Cat",
      "type": "SAYS",
      "words": "lives a Hatter: and in _that_ direction,"
    },
    {
      "addressee": null,
      "speaker": "the Cat",
      "type": "SAYS",
      "words": "lives a March Hare. Visit either you like: they’re both mad."
    },
    {
      "addressee": null,
      "speaker": "Alice",
      "type": "SAYS",
      "words": "But I don’t want to go among mad people,"
    },
    {
      "addressee": null,
      "speaker": "the Cat",
      "type": "SAYS",
      "words": "Oh, you can’t help that,"
    },
    {
      "addressee": null,
      "speaker": "the Cat",
