      "words": "Nonsense!"
    },
    {
      "addressee": "the Queen",
      "speaker": "the King",
      "type": "SAYS",
      "words": "Consider, my dear: she is only a child!"
    },
    {
      "addressee": "the Knave of Hearts",
      "speaker": "the Queen",
      "type": "SAYS",
      "words": "Turn them over!"
    },
    {
      "addressee": null,
      "speaker": "the Queen",
      "type": "SAYS",
      "words": "Get up!"
    },
    {
      "addressee": null,
      "speaker": "the Queen",
