    },
    {
      "addressee": null,
      "speaker": "the Dodo",
      "type": "SAYS",
      "words": "Hand it over here"
    },
    {
      "addressee": null,
      "speaker": "the Dodo",
      "type": "SAYS",
      "words": "We beg your acceptance of this elegant thimble;"
    },
    {
      "addressee": null,
      "speaker": "Alice",
      "type": "SAYS",
      "words": "You promised to tell me your history, you know"
    },
    {
      "addressee": null,
      "speaker": "Alice",
      "type": "SAYS",
      "words": "and why it is you hate—C and D"
    },
    {
      "addressee": "Alice",
      "speaker": "the Mouse",
      "type": "SAYS",
      "words": "Mine is a long and a sad tale!"
    },
    {
      "addressee": null,
      "speaker": "Alice",
      "type": "SAYS",
      "words": "It _is_ a long tail, certainly"
    },
    {
      "addressee": null,
      "speaker": "Alice",
      "type": "SAYS",
      "words": "but why do you call it sad?"
    },
    {
      "addressee": "a mouse",
      "speaker": "Fury",
      "type": "SAYS",
      "words": "Let us both go to law: _I_ will prosecute _you_.—Come, I’ll take no denial; We must have a trial: For really this morning I’ve nothing to do."
    },
    {
      "addressee": null,
      "speaker": "Fury",
      "type": "SAYS",
      "words": "I’ll be judge, I’ll be jury"
    },
    {
      "addressee": null,
      "speaker": "Fury",
      "type": "SAYS",
      "words": "I’ll try the whole cause, and condemn you to death."
    },
    {
      "addressee": "Alice",
      "speaker": "the Mouse",
      "type": "SAYS",
      "words": "You are not attending!"
    },
    {
      "addressee": "Alice",
      "speaker": "the Mouse",
      "type": "SAYS",
      "words": "What are you thinking of?"
    },
    {
      "addressee": null,
      "speaker": "Alice",
      "type": "SAYS",
      "words": "I beg your pardon"
    },
    {
      "addressee": null,
      "speaker": "Alice",
      "type": "SAYS",
      "words": "you had got to the fifth bend, I think?"
    },
    {
      "addressee": null,
      "speaker": "the Mouse",
      "type": "SAYS",
      "words": "I had _not!_"
    },
    {
      "addressee": null,
      "speaker": "Alice",
      "type": "SAYS",
      "words": "A knot!"
    },
    {
      "addressee": null,
      "speaker": "Alice",
      "type": "SAYS",
      "words": "Oh, do let me help to undo it!"
    },
    {
      "addressee": null,
      "speaker": "the Mouse",
      "type": "SAYS",
      "words": "I shall do nothing of the sort"
    },
    {
      "addressee": null,
      "speaker": "the Mouse",
      "type": "SAYS",
      "words": "You insult me by talking such nonsense!"
    },
    {
      "addressee": null,
      "speaker": "Alice",
      "type": "SAYS",
      "words": "I didn’t mean it!"
    },
    {
      "addressee": null,
      "speaker": "Alice",
      "type": "SAYS",
      "words": "But you’re so easily offended, you know!"
    }
