{
  "entities": [
    {
      "aliases": [],
      "chapter": null,
      "description": "A girl who eats bits of the mushroom, shrinks until her chin presses against her foot, and then finds her neck grown to an immense length like a serpent's among the treetops.",
      "kind": "Character",
      "mentions": [
        "Alice",
        "poor Alice"
      ],
      "name": "Alice"
    },
    {
      "aliases": [],
      "chapter": null,
      "description": "Exactly three inches high; it smokes a hookah, sits on the mushroom, is easily offended, and crawls away remarking that one side of the mushroom will make you grow taller and the other shorter.",
      "kind": "Character",
      "mentions": [
        "the Caterpillar"
      ],
      "name": "Caterpillar"
    },
    {
      "aliases": [],
      "chapter": null,
